using System.Globalization;
using System.Text;
using DK2.Core;
using DK2.Data;
using DK2.Data.Model;
using DK2.Simulation;
using DK2.Simulation.Systems;

namespace DK2.Harness;

/// <summary>
/// <c>keeper-knowledge</c> (campaign bot stage 3 plan, Task 3a): the room facts a keeper can know
/// from the game's own definitions, generated by running the simulation's rules on synthetic
/// rooms, never written by hand. For every buildable room and each square side, one room of that
/// side is painted for player 3 into Level 1's map, the furniture system runs one tick, and the
/// room's floor slots, capacity, attraction contribution and stored gold are read; with them the
/// room's cost, its recommended size and the creatures it draws. An authoring tool, not run-time.
/// </summary>
internal static class KeeperKnowledgeCommand
{
    public const int MinSide = 3, MaxSide = 7;
    private const byte Keeper = 3;
    private const string MapLevel = "level1";

    /// <summary>Square sides a room is measured at.</summary>
    public static IEnumerable<int> Sides
    {
        get
        {
            return Enumerable.Range(MinSide, MaxSide - MinSide + 1);
        }
    }

    /// <summary>The terrain set on the ring around a measured square: a reinforced wall (solid, takes room walls),
    /// as a room dug out and claimed ends up; and dirt path (open ground), as a room built into a cavern.</summary>
    public const byte WalledRim = 9, OpenRim = 3;

    /// <summary>One room of one side, as the simulation's rules make it: walled all round, and the
    /// furniture-dependent values again on open ground (wall furniture needs a wall).</summary>
    public sealed record SizeFacts(int Side, int Tiles, int FloorSlots, int Capacity, int Attraction, int Gold, int Furniture,
        int OpenCapacity, int OpenAttraction, int OpenFurniture);

    /// <summary>A creature this room draws: <paramref name="MinTiles"/> of the room type it needs in
    /// all (<c>PortalRules.IsAttracted</c>), and whether this room's attraction caps how many come
    /// (<paramref name="Budget"/>: its first attraction entry, not a Lair; <c>AttractionBudget.Admits</c>).</summary>
    public sealed record Attracted(byte CreatureId, string Name, int MinTiles, bool Budget, bool Portal);

    public sealed record RoomFacts(RoomTypeId Room, string Name, int CostPerTile, int RecommendedX, int RecommendedY,
        IReadOnlyList<SizeFacts> Sizes, IReadOnlyList<Attracted> Attracts);

    /// <summary>What a creature type needs before the portal offers it: room tiles by type, gold, mana;
    /// the room whose attraction caps its count, or none when it is uncapped.</summary>
    public sealed record Needs(byte CreatureId, string Name, IReadOnlyList<(RoomTypeId Room, int Tiles)> Rooms, int Gold, int Mana,
        RoomTypeId? BudgetRoom, bool Uncapped, bool Portal);

    /// <summary>Whether a keeper's portal can ever offer the type (<c>PortalRules.CanComeFromPortal</c>): heroes and
    /// the Graveyard's and Prison's creatures cannot, whatever their attraction entries say.</summary>
    private static bool FromKeeperPortal(GameDatabase database, CreatureDef creature)
    {
        return PortalRules.CanComeFromPortal(creature, database.Room(RoomTypeId.Portal));
    }

    /// <summary>Each creature's portal requirements, read as <c>PortalRules.IsAttracted</c> and
    /// <c>AttractionBudget.Admits</c> read them: kind 1 a room type's total tiles, 2 gold, 3 mana (room id
    /// and size packed); the first entry, when it is a room other than the Lair, caps the count.</summary>
    public static IReadOnlyList<Needs> CreatureNeeds(GameDatabase database)
    {
        return [.. database.Creatures.Values.Where(c => c.Attractions.Any(a => a.Present != 0)).OrderBy(c => c.CreatureId).Select(c =>
        {
            var rooms = new List<(RoomTypeId, int)>();
            int gold = 0, mana = 0;
            foreach (CreatureAttraction a in c.Attractions)
            {
                int packed = (a.RoomId & 0xFF) | ((a.RoomSize & 0xFF) << 8);
                if (a.Present == 1 && a.RoomId != 0) { rooms.Add(((RoomTypeId)a.RoomId, a.RoomSize)); } else if (a.Present == 2) { gold = Math.Max(gold, packed); } else if (a.Present == 3) { mana = Math.Max(mana, packed); } }
            CreatureAttraction first = c.Attractions[0];
            bool roomFirst = first.Present == 1 && first.RoomId != 0;
            bool lair = roomFirst && first.RoomId == (byte)RoomTypeId.Lair;
            return new Needs(c.CreatureId, c.Name.Trim(), rooms, gold, mana,
                roomFirst && !lair ? (RoomTypeId)first.RoomId : null, Uncapped: !roomFirst || lair, FromKeeperPortal(database, c));
        })];
    }

    public static int Run(string install, string? output, TextWriter log)
    {
        GameDatabase database = GameDatabaseLoader.Load(install);
        LevelMap map = GameDatabaseLoader.LoadCampaignMap(install, MapLevel)
            ?? throw new InvalidOperationException($"campaign map {MapLevel} not found under {install}");
        IReadOnlyList<RoomFacts> facts = Measure(database, map);
        string yaml = Yaml(facts, database);
        if (output is null)
        {
            log.Write(yaml);
        }
        else
        {
            Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);
            File.WriteAllText(output, yaml, new UTF8Encoding(false));
            log.WriteLine($"wrote {output}: {facts.Count} rooms, sides {MinSide}-{MaxSide}");
        }
        return 0;
    }

    /// <summary>Every buildable room's facts, in room id order.</summary>
    public static IReadOnlyList<RoomFacts> Measure(GameDatabase database, LevelMap map)
    {
        var rooms = new List<RoomFacts>();
        foreach (RoomDef room in database.Rooms.Values.Where(r => (r.Flags & RoomFlags.Buildable) != 0).OrderBy(r => r.RoomId))
        {
            var type = (RoomTypeId)room.RoomId;
            var sizes = new List<SizeFacts>();
            foreach (int side in Sides)
            {
                Measured walled = MeasureSquare(database, map, room, side, WalledRim);
                Measured open = MeasureSquare(database, map, room, side, OpenRim);
                sizes.Add(new SizeFacts(side, walled.Tiles, walled.FloorSlots, walled.Capacity, walled.Attraction, walled.Gold,
                    walled.Furniture, open.Capacity, open.Attraction, open.Furniture));
            }
            var attracts = database.Creatures.Values
                .SelectMany(c => c.Attractions.Select((a, slot) => (a, slot)).Where(x => x.a.Present == 1 && x.a.RoomId == room.RoomId)
                    .Select(x => new Attracted(c.CreatureId, c.Name.Trim(), x.a.RoomSize, Budget: x.slot == 0 && type != RoomTypeId.Lair,
                        Portal: FromKeeperPortal(database, c))))
                .OrderBy(a => a.CreatureId).ToList();
            rooms.Add(new RoomFacts(type, room.Name, room.Cost, room.RecommendedSizeX, room.RecommendedSizeY, sizes, attracts));
        }
        return rooms;
    }

    private sealed record Measured(int Tiles, int FloorSlots, int Capacity, int Attraction, int Gold, int Furniture);

    /// <summary>One square of <paramref name="side"/>, its ring of tiles (diagonals included) set to
    /// <paramref name="rim"/>, which must be a wall (<see cref="WalledRim"/>) or open ground as stated.</summary>
    private static Measured MeasureSquare(GameDatabase database, LevelMap map, RoomDef def, int side, byte rim)
    {
        var world = WorldState.FromMap(database, map, map.Tiles.Select(t => t.PlayerId).Append(Keeper).Distinct());
        // Away from the map's edge, so the square and its rim fit whatever the side.
        int x0 = (world.Width - side) / 2, y0 = (world.Height - side) / 2;
        TerrainFlags wall = TerrainFlags.Solid | TerrainFlags.AllowRoomWalls;
        bool walled = (database.TerrainById(rim).Flags & wall) == wall;
        if (walled != (rim == WalledRim))
        {
            throw new InvalidOperationException($"terrain {rim} ({database.TerrainById(rim).Name}) is not the {(rim == WalledRim ? "wall" : "open ground")} it stands for");
        }

        for (int y = y0 - 1; y <= y0 + side; y++)
        {
            for (int x = x0 - 1; x <= x0 + side; x++)
            {
                ref TileState tile = ref world.Tile(x, y);
                if (x >= x0 && x < x0 + side && y >= y0 && y < y0 + side)
                {
                    RoomRules.Place(database, ref tile, def, Keeper);
                }
                else
                {
                    tile.TerrainId = rim;
                }
            }
        }

        new GameSimulation(database, world, seed: 1, [new AutoFurnitureSystem()]).Tick();

        int index = (y0 * world.Width) + x0;
        RoomInstance room = RoomIndex.Build(world, database).Single(r => r.TileIndices.Contains(index));
        int capacity = AutoFurnitureRules.TryTotalCapacity(world, room, out int c) ? c : -1;
        int gold = room.TileIndices.Sum(t => GoldStore.Capacity(world, database, t));
        var tiles = new HashSet<int>(room.TileIndices);
        int furniture = world.Objects.Count(o => o.AutoPlaced && tiles.Contains(o.TileIndex));
        return new Measured(room.TileCount, AutoFurnitureRules.FloorSlotCount(world, room), capacity,
            AttractionBudget.Contribution(world, room), gold, furniture);
    }

    /// <summary>The facts file: deterministic, so a regeneration that changes nothing changes no byte.</summary>
    public static string Yaml(IReadOnlyList<RoomFacts> rooms, GameDatabase database)
    {
        var s = new StringBuilder();
        s.Append("# Generated by `DK2.Harness keeper-knowledge`; never edit by hand (campaign bot stage 3, Task 3a).\n");
        s.Append("# Each room is painted as a side x side square for player 3 on Level 1's map, ringed by reinforced\n");
        s.Append("# wall (terrain 9: solid, takes room walls, as a dug and claimed room is), the furniture system runs\n");
        s.Append("# one tick, and the simulation's own rules are read: floor_slots (AutoFurnitureRules: interior\n");
        s.Append("# tiles; checkerboard rooms one parity), capacity (TryTotalCapacity), attraction\n");
        s.Append("# (AttractionBudget.Contribution: the portal admits a capped type while its rooms' sum exceeds\n");
        s.Append("# the number of that type held), gold (GoldStore), furniture (auto-placed objects). The open_*\n");
        s.Append("# values ring the square with dirt path (terrain 3) instead: wall furniture needs a wall, so a room\n");
        s.Append("# on open ground or with gaps in its walls can draw less. These are our rules' readings; their\n");
        s.Append("# confidence is the research's: binary-entrance.md, auto-placed-furniture.md, rooms-and-gold.md.\n");
        s.Append(Invariant($"hash_version: {GameSimulation.CurrentHashVersion}\n"));
        s.Append("rooms:\n");
        foreach (RoomFacts room in rooms)
        {
            s.Append(Invariant($"  - room: {room.Room}\n"));
            s.Append(Invariant($"    name: \"{room.Name.Trim()}\"\n"));
            if (room.Room == RoomTypeId.Lair)
            {
                s.Append("    note: \"a Lair-attracted type is never capped and needs no Lair (AttractionBudget.Admits); attraction here is unused\"\n");
            }

            if (room.Room == RoomTypeId.Graveyard)
            {
                s.Append("    note: \"our AttractionBudget reads no Graveyard arm (capacity -1); the research records its floor slots (auto-placed-furniture.md section 5, Q60). No portal creature is capped by it\"\n");
            }

            s.Append(Invariant($"    cost_per_tile: {room.CostPerTile}\n"));
            s.Append(Invariant($"    recommended_size: [{room.RecommendedX}, {room.RecommendedY}]\n"));
            s.Append("    sizes:\n");
            foreach (SizeFacts z in room.Sizes)
            {
                s.Append(Invariant($"      - {{ side: {z.Side}, tiles: {z.Tiles}, floor_slots: {z.FloorSlots}, capacity: {z.Capacity}, attraction: {z.Attraction}, gold: {z.Gold}, furniture: {z.Furniture}, open_capacity: {z.OpenCapacity}, open_attraction: {z.OpenAttraction}, open_furniture: {z.OpenFurniture} }}\n"));
            }

            if (room.Attracts.Count == 0)
            {
                s.Append("    attracts: []\n");
            }
            else
            {
                s.Append("    attracts:\n");
                foreach (Attracted a in room.Attracts)
                {
                    s.Append(Invariant($"      - {{ creature: {a.CreatureId}, name: \"{a.Name}\", min_tiles: {a.MinTiles}, capped_by_this_room: {Bool(a.Budget)}, portal: {Bool(a.Portal)} }}\n"));
                }
            }
        }
        s.Append("# Portal requirements per creature: every room type's total tiles, gold and mana must be met;\n");
        s.Append("# budget_room's attraction (sizes[].attraction, summed over its rooms) caps how many come, each\n");
        s.Append("# one held taking 1 off; an uncapped type (its first need is a Lair, or no room) is not capped.\n");
        s.Append("# portal: false marks a type a keeper's portal never offers (PortalRules.CanComeFromPortal: heroes,\n");
        s.Append("# and the Graveyard's and Prison's creatures), whatever its attraction entries say.\n");
        s.Append("creatures:\n");
        foreach (Needs n in CreatureNeeds(database))
        {
            string needs = string.Join(", ", n.Rooms.Select(r => Invariant($"{{ room: {r.Room}, tiles: {r.Tiles} }}")));
            s.Append(Invariant($"  - {{ creature: {n.CreatureId}, name: \"{n.Name}\", rooms: [{needs}], gold: {n.Gold}, mana: {n.Mana}, budget_room: {n.BudgetRoom?.ToString() ?? "none"}, uncapped: {Bool(n.Uncapped)}, portal: {Bool(n.Portal)} }}\n"));
        }
        return s.ToString();

        static string Bool(bool value)
        {
            return value ? "true" : "false";
        }
    }

    private static string Invariant(FormattableString value)
    {
        return value.ToString(CultureInfo.InvariantCulture);
    }
}
